// Build a platformKey → socialMediaId map from PostFast's /social-accounts response.
// PostFast returns either a bare array of account objects, or {data: [...]} — handle both.
// Each account has at least { id, platform } where platform is a string like
// 'INSTAGRAM', 'TIKTOK', 'YOUTUBE', 'LINKEDIN', 'X', 'TWITTER', etc.

const raw = $input.all().map(i => i.json);
let accounts = raw;
// If n8n got a single object with a data/items/results array, unwrap it.
if (raw.length === 1 && raw[0] && typeof raw[0] === 'object') {
  if (Array.isArray(raw[0].data)) accounts = raw[0].data.map(a => a);
  else if (Array.isArray(raw[0].items)) accounts = raw[0].items.map(a => a);
  else if (Array.isArray(raw[0].results)) accounts = raw[0].results.map(a => a);
}

const platformMap = {};
const summary = [];
for (const acc of accounts) {
  if (!acc || !acc.id) continue;
  const platform = String(acc.platform || acc.provider || '').toUpperCase();
  if (!platform) continue;
  platformMap[platform] = acc.id;
  summary.push({ platform, id: acc.id, handle: acc.handle || acc.name || null });
}

return [{ json: { platformMap, summary, rawCount: accounts.length } }];

// For each Notion short, parse its Description into per-platform captions,
// resolve each platform to a PostFast socialMediaId via the map built upstream,
// and emit one item containing the full POST body for /social-posts.
//
// Description format example (each block starts on its own line, separated by blanks):
//   YT: Caption for YouTube Shorts ... | Tags: k1, k2
//   SM: Caption for Instagram + TikTok (same text) ...
//   LI: LinkedIn caption ...
//   X: Caption for X/Twitter ...

const PREFIX_TO_PLATFORMS = {
  YT: ['YOUTUBE'],
  SM: ['INSTAGRAM', 'TIKTOK'],
  LI: ['LINKEDIN'],
  X:  ['X', 'TWITTER'], // match either naming
};

const platformMap = $('Code — Build Platform Map').first().json.platformMap || {};

const extractText = (v) => {
  if (v == null) return '';
  if (typeof v === 'string') return v;
  if (Array.isArray(v)) return v.map(r => r.plain_text || r.text?.content || r.text || '').join('');
  if (typeof v === 'object') {
    if (v.plain_text) return v.plain_text;
    if (typeof v.text === 'string') return v.text;
    if (Array.isArray(v.title)) return v.title.map(r => r.plain_text || '').join('');
    if (Array.isArray(v.rich_text)) return v.rich_text.map(r => r.plain_text || '').join('');
  }
  return String(v ?? '');
};

const extractDate = (v) => {
  if (!v) return null;
  if (typeof v === 'string') return v;
  if (v.start) return v.start;
  if (v.date && v.date.start) return v.date.start;
  return null;
};

const props = $json.properties || $json;
const titleText = extractText(props['Titre']);
const descText = extractText(props['Description']);
const dateRaw = extractDate(props['Date de Publication']);
const notionPageId = $json.id || ($json.url && $json.url.split('/').pop().split('?')[0]) || '';

if (!dateRaw) {
  throw new Error(`Short "${titleText}" (id=${notionPageId}) has no Date de Publication.`);
}

// Shorts with only a date (no time) default to 09:00 UTC.
// Adjust here if you want a different hour/timezone.
const scheduledAt = /T\d/.test(dateRaw)
  ? new Date(dateRaw).toISOString()
  : new Date(`${dateRaw}T09:00:00.000Z`).toISOString();

// Split the description into prefixed blocks.
const BLOCK_REGEX = /(^|\n)\s*(YT|SM|LI|X)\s*:\s*/g;
const matches = [];
let m;
while ((m = BLOCK_REGEX.exec(descText)) !== null) {
  matches.push({ prefix: m[2], start: m.index + m[0].length });
}
if (matches.length === 0) {
  throw new Error(`Short "${titleText}" (id=${notionPageId}) has no YT:/SM:/LI:/X: blocks in its Description.`);
}

const blocks = [];
for (let i = 0; i < matches.length; i++) {
  const end = i + 1 < matches.length
    ? matches[i + 1].start - matches[i + 1].prefix.length - 2
    : descText.length;
  let caption = descText.slice(matches[i].start, end).trim();
  // Strip trailing "| Tags: ..." marker that only the YT block carries.
  caption = caption.replace(/\s*\|\s*Tags\s*:.*$/is, '').trim();
  blocks.push({ prefix: matches[i].prefix, caption });
}

// Build posts array.
const posts = [];
const missingPlatforms = [];
for (const { prefix, caption } of blocks) {
  const platforms = PREFIX_TO_PLATFORMS[prefix] || [];
  // SM fans out to INSTAGRAM + TIKTOK; other prefixes map 1:1.
  for (const p of platforms) {
    const socialMediaId = platformMap[p];
    if (!socialMediaId) {
      missingPlatforms.push(p);
      continue;
    }
    posts.push({
      content: caption,
      scheduledAt,
      socialMediaId,
    });
    // Break after first match for prefixes that accept either X or TWITTER naming.
    if (prefix === 'X' && (p === 'X' || p === 'TWITTER')) break;
  }
}

if (posts.length === 0) {
  throw new Error(`Short "${titleText}" (id=${notionPageId}): no posts could be built. Missing platforms: ${missingPlatforms.join(', ') || 'none'}. platformMap=${JSON.stringify(platformMap)}`);
}

return {
  json: {
    notionPageId,
    titleText,
    scheduledAt,
    postCount: posts.length,
    missingPlatforms,
    body: {
      posts,
      controls: {},
    },
  },
};
